WITH flattened AS (SELECT id, plan, effective_from, currency, tier_value FROM price_tiers LATERAL VIEW EXPLODE(tier_prices) e AS tier_value) SELECT DATE_TRUNC('WEEK', effective_from) AS week_start, CASE WHEN tier_value >= 65 THEN 'PREMIUM' ELSE 'STANDARD' END AS tier_value_tier, AVG(tier_value) FILTER (WHERE currency = 'EUR') AS eur_avg_tier_value, AVG(tier_value) AS avg_tier_value FROM flattened GROUP BY DATE_TRUNC('WEEK', effective_from), CASE WHEN tier_value >= 65 THEN 'PREMIUM' ELSE 'STANDARD' END ORDER BY avg_tier_value DESC NULLS FIRST;
